/// <summary>Comando del puente con el tipo de su payload y de su respuesta.</summary>
public sealed class BridgeCommand<TPayload, TResponse>(string name)
{
    public string Name { get; } = name;
}

/// <summary>Evento del puente con el tipo de su payload.</summary>
public sealed class BridgeEvent<TPayload>(string name)
{
    public string Name { get; } = name;
}

/// <summary>Comandos que la aplicación envía al motor.</summary>
public static class BridgeCommands
{
    /// <summary>Comprueba que el motor responde y mide la latencia del puente.</summary>
    public static readonly BridgeCommand<AppPing, AppPong> AppPing = new("app.ping");

    /// <summary>Selecciona todos los objetos del grupo en el que está el usuario, o del documento si no ha entrado en ninguno.</summary>
    public static readonly BridgeCommand<DocumentRef, DocumentRef> SelectionSelectAll = new("selection.selectAll");

    /// <summary>Quita de &lt;defs&gt; las definiciones a las que no llega nada del documento, tampoco a través de otras definiciones (degradados, patrones, recortes, símbolos…). Es un paso del historial; sin nada que quitar, no hay paso.</summary>
    public static readonly BridgeCommand<DocumentRef, DefinitionsCleaned> DocumentCleanDefinitions = new("document.cleanDefinitions");

    /// <summary>Mueve, redimensiona o gira la selección hasta los valores del panel de propiedades, en un paso que se puede deshacer.</summary>
    public static readonly BridgeCommand<SelectionGeometry, DocumentRef> SelectionSetGeometry = new("selection.setGeometry");

    /// <summary>Cambia el relleno, el trazo, su grosor o la opacidad de la selección tocando lo mínimo del archivo. Los cambios seguidos de las mismas propiedades son un solo paso del historial.</summary>
    public static readonly BridgeCommand<StyleChange, ObjectChange> SelectionSetStyle = new("selection.setStyle");

    /// <summary>Aplica o cambia un degradado en el relleno o el trazo de la selección: tipo, paradas y repetición. Crea el degradado si hace falta y copia el que compartan otros objetos. Los cambios seguidos de las posiciones o colores de las mismas paradas son un solo paso del historial.</summary>
    public static readonly BridgeCommand<GradientRequest, ObjectChange> SelectionSetGradient = new("selection.setGradient");

    /// <summary>Pinta el relleno o el trazo de la selección con un degradado de la biblioteca, compartiendo sus paradas o con una copia. Se puede deshacer.</summary>
    public static readonly BridgeCommand<UseGradient, ObjectChange> SelectionUseGradient = new("selection.useGradient");

    /// <summary>Cambia la fuente, el tamaño, el peso, la cursiva, la alineación o el interlineado de los textos seleccionados. Los cambios seguidos de las mismas propiedades se funden en un paso del historial.</summary>
    public static readonly BridgeCommand<TextChange, ObjectChange> SelectionSetText = new("selection.setText");

    /// <summary>Cambia propiedades propias de la forma seleccionada (radio de las esquinas, lados de un polígono…) en un paso que se puede deshacer. Los cambios seguidos de la misma propiedad son un solo paso del historial.</summary>
    public static readonly BridgeCommand<ShapeChange, ObjectChange> SelectionSetShape = new("selection.setShape");

    /// <summary>Trae al frente, envía al fondo, sube o baja un nivel la selección. Se puede deshacer.</summary>
    public static readonly BridgeCommand<ObjectArrange, ObjectChange> ObjectArrange = new("object.arrange");

    /// <summary>Convierte en trazados (&lt;path&gt;) las formas seleccionadas (rectángulo, elipse, círculo, línea, polígono, polilínea) sin cambiar su aspecto, conservando sus atributos. Se puede deshacer.</summary>
    public static readonly BridgeCommand<DocumentRef, ObjectChange> ObjectToPath = new("object.toPath");

    /// <summary>Con la herramienta Vértices en un trazado, hace esquina, suaves o simétricos los nodos seleccionados, o rectos o curvos los segmentos entre ellos. changed es false si no había nada que cambiar. Se puede deshacer.</summary>
    public static readonly BridgeCommand<PathNodesChange, ObjectChange> PathNodes = new("path.nodes");

    /// <summary>Operación del menú Trazado sobre la selección: cerrar o abrir trazados (con la herramienta Vértices, abrir por el nodo seleccionado), invertir su dirección, combinar las formas seleccionadas en un trazado o separar un trazado en sus subtrazados. changed es false si no había nada que hacer. Se puede deshacer.</summary>
    public static readonly BridgeCommand<PathOperation, ObjectChange> PathOperation = new("path.operation");

    /// <summary>Con la herramienta Vértices, redondea las esquinas seleccionadas con el mismo radio (o lo quita con 0); con all, todas las esquinas de los objetos seleccionados. La forma pasa a ser un trazado que guarda sus vértices y radios en atributos data-winvector-*. changed es false si no había esquinas que redondear. Se puede deshacer.</summary>
    public static readonly BridgeCommand<CornerRadiusChange, ObjectChange> PathCornerRadius = new("path.cornerRadius");

    /// <summary>Agrupa la selección en un &lt;g&gt; sin cambiar su aspecto. Se puede deshacer.</summary>
    public static readonly BridgeCommand<DocumentRef, ObjectChange> ObjectGroup = new("object.group");

    /// <summary>Desagrupa los grupos seleccionados sin cambiar su aspecto; los que cambiarían (opacidad, filtro, recorte, máscara) se dejan. Se puede deshacer.</summary>
    public static readonly BridgeCommand<DocumentRef, ObjectChange> ObjectUngroup = new("object.ungroup");

    /// <summary>Duplica la selección junto al original y selecciona las copias. Se puede deshacer.</summary>
    public static readonly BridgeCommand<DocumentRef, ObjectChange> SelectionDuplicate = new("selection.duplicate");

    /// <summary>Elimina la selección. Se puede deshacer.</summary>
    public static readonly BridgeCommand<DocumentRef, ObjectChange> SelectionDelete = new("selection.delete");

    /// <summary>Devuelve la selección como SVG independiente; la aplicación lo pone en el portapapeles de Windows.</summary>
    public static readonly BridgeCommand<DocumentRef, ClipboardContent> ClipboardCopy = new("clipboard.copy");

    /// <summary>Pega un SVG en el puntero, o desplazado respecto a su posición original si el puntero no está sobre el lienzo, y lo selecciona. Se puede deshacer.</summary>
    public static readonly BridgeCommand<ClipboardPaste, ClipboardPasteResult> ClipboardPaste = new("clipboard.paste");

    /// <summary>Carga un documento SVG en el motor con el identificador que le asigna la aplicación.</summary>
    public static readonly BridgeCommand<DocumentLoad, DocumentLoadResult> DocumentLoad = new("document.load");

    /// <summary>Devuelve el SVG de un documento listo para guardarlo.</summary>
    public static readonly BridgeCommand<DocumentRef, DocumentContent> DocumentSerialize = new("document.serialize");

    /// <summary>Muestra un documento en el lienzo; los demás quedan ocultos.</summary>
    public static readonly BridgeCommand<DocumentRef, DocumentState> DocumentActivate = new("document.activate");

    /// <summary>Descarta un documento del motor.</summary>
    public static readonly BridgeCommand<DocumentRef, DocumentRef> DocumentClose = new("document.close");

    /// <summary>Deshace el último paso del historial de un documento. Si no hay nada que deshacer, no cambia nada.</summary>
    public static readonly BridgeCommand<DocumentRef, HistoryState> HistoryUndo = new("history.undo");

    /// <summary>Rehace el último paso deshecho de un documento. Si no hay nada que rehacer, no cambia nada.</summary>
    public static readonly BridgeCommand<DocumentRef, HistoryState> HistoryRedo = new("history.redo");

    /// <summary>Acerca, aleja, ajusta a la ventana o muestra a tamaño real un documento. Responde con el zoom resultante.</summary>
    public static readonly BridgeCommand<ViewZoom, ViewportChanged> ViewZoom = new("view.zoom");

    /// <summary>Muestra u oculta las reglas y la cuadrícula y activa el ajuste a la cuadrícula.</summary>
    public static readonly BridgeCommand<ViewOptions, ViewOptions> ViewSetOptions = new("view.setOptions");

    /// <summary>Cambia la herramienta activa del lienzo.</summary>
    public static readonly BridgeCommand<ToolState, ToolState> ToolSelect = new("tool.select");

    /// <summary>Cambia el tamaño de la mesa de trabajo de un documento. Se puede deshacer.</summary>
    public static readonly BridgeCommand<Artboard, Artboard> ArtboardSet = new("artboard.set");
}

/// <summary>Eventos que el motor envía a la aplicación.</summary>
public static class BridgeEvents
{
    /// <summary>El motor ha cargado y puede recibir comandos.</summary>
    public static readonly BridgeEvent<EngineReady> EngineReady = new("engine.ready");

    /// <summary>La selección del documento ha cambiado.</summary>
    public static readonly BridgeEvent<SelectionChanged> SelectionChanged = new("selection.changed");

    /// <summary>Al editar sus vértices, un rectángulo o un polígono o estrella de WinVector ha pasado a ser un polígono normal. La aplicación lo avisa en la barra de estado.</summary>
    public static readonly BridgeEvent<ShapeConverted> ShapeConverted = new("shape.converted");

    /// <summary>Con la herramienta Texto (o con doble clic), se ha intentado editar un texto que no se puede editar en el lienzo. La aplicación explica por qué en la barra de estado.</summary>
    public static readonly BridgeEvent<TextLocked> TextLocked = new("text.locked");

    /// <summary>Las fuentes que usan los textos de un documento: al cargarlo y cuando cambian. La aplicación avisa de las que no están instaladas; el documento no cambia.</summary>
    public static readonly BridgeEvent<DocumentFonts> DocumentFonts = new("document.fonts");

    /// <summary>La biblioteca de degradados de un documento: al cargarlo y cuando cambia.</summary>
    public static readonly BridgeEvent<DocumentGradients> DocumentGradients = new("document.gradients");

    /// <summary>Han cambiado los nodos seleccionados de la forma que se edita con la herramienta Vértices, o lo que se puede hacer con ellos. La aplicación habilita las órdenes de nodos del menú Trazado y del panel.</summary>
    public static readonly BridgeEvent<NodeSelection> NodesChanged = new("nodes.changed");

    /// <summary>El usuario ha pedido el menú contextual del lienzo (clic derecho, Mayús+F10 o la tecla de menú). La aplicación lo abre en el punto indicado.</summary>
    public static readonly BridgeEvent<ContextMenuRequest> CanvasContextMenu = new("canvas.contextMenu");

    /// <summary>El motor ha recibido un mensaje que no puede procesar o ha sufrido un error interno.</summary>
    public static readonly BridgeEvent<BridgeError> Error = new("error");

    /// <summary>Un documento ha cambiado. La revisión identifica su estado: cambia con cada edición y, al deshacer o rehacer, vuelve a la de ese estado.</summary>
    public static readonly BridgeEvent<DocumentState> DocumentChanged = new("document.changed");

    /// <summary>El usuario ha soltado archivos sobre el lienzo. Los archivos viajan como objetos adicionales del mensaje de WebView2, con su ruta.</summary>
    public static readonly BridgeEvent<FilesDropped> FilesDropped = new("files.dropped");

    /// <summary>Ha cambiado el historial de deshacer de un documento.</summary>
    public static readonly BridgeEvent<HistoryState> HistoryChanged = new("history.changed");

    /// <summary>Ha cambiado el zoom de un documento.</summary>
    public static readonly BridgeEvent<ViewportChanged> ViewportChanged = new("viewport.changed");

    /// <summary>La herramienta activa ha cambiado desde el lienzo (por ejemplo, con su atajo de teclado).</summary>
    public static readonly BridgeEvent<ToolState> ToolChanged = new("tool.changed");

    /// <summary>El tamaño de la mesa de trabajo de un documento es nuevo o ha cambiado (también al cargarlo).</summary>
    public static readonly BridgeEvent<Artboard> ArtboardChanged = new("artboard.changed");

    /// <summary>Con el lienzo enfocado, WebView2 entrega el teclado a la página y los atajos de la ventana no se disparan: el motor atiende los suyos (deshacer, zoom, seleccionar todo) y envía los demás a la aplicación.</summary>
    public static readonly BridgeEvent<KeyboardShortcut> KeyboardShortcut = new("keyboard.shortcut");
}

